ext('c12_eng_ch19',[
C("🔥","अग्नि का भारतीय महत्व",["वेदों में अग्नि देवता","यज्ञ और हवन का केंद्र","विवाह के फेरे अग्नि के साक्ष्य में","अंतिम संस्कार में अग्नि"],"भारतीय संस्कृति में अग्नि का बहुत ऊँचा स्थान है। ऋग्वेद का पहला मंत्र ही अग्नि की स्तुति से शुरू होता है। यज्ञ और हवन में अग्नि देवताओं तक आहुति पहुँचाने का माध्यम मानी गई है। विवाह के फेरे भी अग्नि के सामने लिए जाते हैं और जीवन की अंतिम यात्रा में भी अग्नि ही शरीर को पंचतत्व में मिलाती है। इस प्रकार अग्नि जन्म से मृत्यु तक हमारे जीवन से जुड़ी है। फ़ायर-हिम का शीर्षक इसी भाव से आता है, जहाँ कवि अग्नि की स्तुति करते हैं, पर मृत्यु के संदर्भ में।"),
C("✍️","केकी दारुवाला का परिचय",["जन्म 1937, लाहौर","भारतीय पुलिस सेवा के अधिकारी","भारतीय अंग्रेज़ी कविता के प्रमुख कवि","साहित्य अकादमी पुरस्कार"],"कवि केकी एन दारुवाला का जन्म उन्नीस सौ सैंतीस में लाहौर में हुआ। वे भारतीय पुलिस सेवा के वरिष्ठ अधिकारी रहे और साथ ही कविता भी लिखते रहे। उन्हें भारतीय अंग्रेज़ी कविता के प्रमुख कवियों में गिना जाता है। उन्हें उन्नीस सौ चौरासी में साहित्य अकादमी पुरस्कार मिला। उनकी कविताओं में हिंसा, मृत्यु, इतिहास और प्रकृति के बिंब बार-बार आते हैं, और भाषा कठोर, सीधी और प्रभावशाली होती है। पुलिस सेवा के अनुभव ने उनकी कविता को यथार्थवादी रंग दिया।"),
C("🌊","श्मशान घाट का दृश्य",["नदी का किनारा","चिता की लपटें","धुआँ और राख","शांत और गंभीर वातावरण"],"कविता का दृश्य नदी तट पर बने श्मशान घाट का है। वहाँ चिता जल रही है, लपटें आसमान की ओर उठ रही हैं और धुआँ हवा में घुल रहा है। चारों ओर एक गंभीर शांति है। बिहार में भी गंगा के किनारे ऐसे घाट हैं, जैसे पटना के गुलाबी घाट और बक्सर, जहाँ यह दृश्य हम देख सकते हैं। कवि इसी दृश्य के सामने खड़े होकर सोचते हैं और अग्नि को संबोधित करते हैं। यह दृश्य हमें सहज ही जीवन की क्षणभंगुरता का एहसास कराता है।"),
C("🔥","अग्नि: शुद्धि और रूपांतरण",["अग्नि सब कुछ जलाकर शुद्ध करती है","भौतिक रूप राख में बदलता है","पंचतत्व में विलय","रूपांतरण का प्रतीक"],"कविता में अग्नि केवल जलाने वाली नहीं, बल्कि शुद्ध करने वाली भी है। भारतीय विचार में शरीर पाँच तत्वों से बना है, पृथ्वी, जल, अग्नि, वायु और आकाश। मृत्यु पर अग्नि शरीर को जलाकर वापस इन तत्वों में मिला देती है। इसलिए अग्नि रूपांतरण का प्रतीक है, जो एक रूप को दूसरे में बदलती है। कवि अग्नि को एक देवता की तरह संबोधित करते हैं और उसकी महिमा की स्तुति करते हैं, जैसे कोई स्तोत्र या हिम में की जाती है। इसी से कविता का नाम फ़ायर-हिम है।"),
C("🧘","मृत्यु पर चिंतन",["मृत्यु अनिवार्य सत्य","शरीर नश्वर, आत्मा अमर","जीवन के प्रति नया दृष्टिकोण","भय नहीं, स्वीकार"],"कविता का केंद्र मृत्यु पर चिंतन है। कवि मानते हैं कि मृत्यु जीवन का अनिवार्य सत्य है, जिससे कोई नहीं बच सकता। भारतीय दर्शन में शरीर को नश्वर और आत्मा को अमर माना गया है। गीता में कहा गया है कि आत्मा न जन्म लेती है, न मरती है। इसी दृष्टिकोण से कवि मृत्यु को भय की चीज़ नहीं, बल्कि जीवन की एक अवस्था के रूप में देखते हैं। यह चिंतन हमें सिखाता है कि मृत्यु से डरने की बजाय जीवन को सार्थक बनाना चाहिए।"),
C("🎭","मानवीकरण और स्तुति शैली",["अग्नि को संबोधन","देवता जैसा आदर","हिम का रूप","गंभीर और शांत स्वर"],"इस कविता में मानवीकरण का प्रयोग है, यानी अग्नि को ऐसे संबोधित किया गया है जैसे वह कोई जीवित व्यक्ति या देवता हो। कवि उससे बात करते हैं और उसकी महिमा गाते हैं। इसका रूप हिम, यानी स्तोत्र या प्रशंसा गीत, जैसा है। पर विषय मृत्यु होने के कारण स्वर गंभीर और शांत रहता है। इस तरह कविता में स्तुति और शोक का एक विचित्र मेल मिलता है। परीक्षा में अलंकार पूछे जाएँ, तो मानवीकरण और प्रतीक का उल्लेख कीजिए।"),
C("🌿","भारतीय परिवेश के बिंब",["नदी, घाट, चिता","राख और धुआँ","रीति-रिवाज और मंत्र","अंग्रेज़ी में भारतीय अनुभव"],"दारुवाला की ख़ासियत है कि वे अंग्रेज़ी में लिखते हुए भी भारतीय परिवेश के बिंब लाते हैं। इस कविता में नदी, घाट, चिता, राख और धुआँ ये सब भारतीय जीवन के जाने-पहचाने दृश्य हैं। इसी वजह से भारतीय पाठक इससे सहज जुड़ पाता है। यह दिखाता है कि अंग्रेज़ी भाषा भारतीय अनुभव को व्यक्त करने का माध्यम बन सकती है। यह भारतीय अंग्रेज़ी कविता की एक बड़ी पहचान है, जिसमें भाषा विदेशी हो सकती है, पर आत्मा पूरी तरह भारतीय है।"),
C("📝","शब्दार्थ दोहराइए",["हिम यानी स्तुति गीत","पायर यानी चिता","क्रीमेशन यानी दाह संस्कार","एसेस यानी राख"],"आइए कुछ शब्द दोहराएँ। हिम यानी स्तुति गीत, पायर यानी चिता, क्रीमेशन यानी दाह संस्कार, एसेस यानी राख और फ़्लेम्स यानी लपटें। साथ में मॉर्टैलिटी यानी नश्वरता, प्यूरिफ़िकेशन यानी शुद्धि और इम्मॉर्टल यानी अमर भी याद कर लीजिए। अब इन शब्दों से अपने वाक्य बनाइए। जैसे फ़ायर इज़ अ सिंबल ऑफ़ प्यूरिफ़िकेशन, यानी अग्नि शुद्धि का प्रतीक है। और द सोल इज़ इम्मॉर्टल, यानी आत्मा अमर है।"),
C("🧩","व्याकरण: अपोस्ट्रोफ़ी और संबोधन",["ओ फ़ायर: सीधा संबोधन","संबोधन में कॉमा का प्रयोग","अपोस्ट्रोफ़ी या एड्रेस","कविता और भाषण में प्रयोग"],"इस कविता में अग्नि को सीधे संबोधित किया गया है, जैसे ओ फ़ायर। इसे अपोस्ट्रोफ़ी या सीधा संबोधन कहते हैं। इसमें उस चीज़ से बात की जाती है जो वहाँ मौजूद नहीं होती या बोल नहीं सकती। संबोधन में आमतौर पर ओ लगाया जाता है और बाद में कॉमा लगाते हैं। जैसे ओ डेथ, व्हेयर इज़ योर स्टिंग, यानी हे मृत्यु, तेरा डंक कहाँ है। भाषण और कविता, दोनों में इसका प्रयोग होता है। अपने शब्दों में प्रकृति या किसी वस्तु को संबोधित करते हुए तीन पंक्तियाँ लिखिए।"),
C("🪔","जीवन को सार्थक बनाना",["मृत्यु निश्चित है, इसलिए समय क़ीमती","दूसरों के काम आना","अच्छे कर्म ही साथ जाते हैं","पढ़ाई और संस्कार में निवेश"],"मृत्यु की सच्चाई हमें डराने के लिए नहीं, जगाने के लिए है। जब हम जान जाते हैं कि समय सीमित है, तो हम उसे बेकार की चीज़ों में नहीं गँवाते। दूसरों के काम आना, अच्छे कर्म करना और पढ़ाई तथा संस्कारों में निवेश करना, यही जीवन को सार्थक बनाता है। हमारे यहाँ कहा जाता है कि अच्छे कर्म ही हमारे साथ जाते हैं। इसलिए इस कविता को पढ़कर निराश होने के बजाय हम सोचें कि हम अपने बचे हुए दिनों को किस तरह उपयोगी बना सकते हैं।"),
C("📌","कविता का सार",["नदी तट पर चिता का दृश्य","अग्नि की स्तुति","मृत्यु अनिवार्य, आत्मा अमर","संदेश: जीवन को सार्थक बनाएँ"],"अब कविता का सार दोहरा लें। केकी एन दारुवाला की फ़ायर-हिम में नदी तट पर चिता जलने का दृश्य है। कवि अग्नि को देवता की तरह संबोधित करते हैं और उसे शुद्धि तथा रूपांतरण का प्रतीक मानते हैं। वे मृत्यु की अनिवार्यता पर चिंतन करते हैं और भारतीय दर्शन के अनुसार शरीर को नश्वर और आत्मा को अमर मानते हैं। संदेश है कि जीवन को सार्थक बनाना चाहिए। इसे अपने शब्दों में पाँच वाक्यों में लिखकर अभ्यास कीजिए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवि का परिचय","अग्नि किसका प्रतीक है","कविता का दृश्य","कविता की सीख"],"परीक्षा के प्रश्न देखिए। पहला, कवि का परिचय। उत्तर, केकी एन दारुवाला, लाहौर में जन्म, पुलिस सेवा, साहित्य अकादमी पुरस्कार, भारतीय अंग्रेज़ी कविता। दूसरा, अग्नि किसका प्रतीक है? उत्तर, शुद्धि, रूपांतरण और जीवन के अंत का। तीसरा, कविता का दृश्य? उत्तर, नदी तट पर श्मशान और जलती चिता। चौथा, सीख? उत्तर, मृत्यु अनिवार्य है, इसलिए जीवन को सार्थक बनाइए। पूरे वाक्य में उत्तर लिखिए।"),
Q("आपके अनुसार मृत्यु के विचार से हमें डरना चाहिए या जीवन को बेहतर जीना सीखना चाहिए?","जीवन को बेहतर जीना सीखना चाहिए, क्योंकि मृत्यु का विचार हमें समय की क़ीमत सिखाता है।","एक सोचने वाला प्रश्न। आपके अनुसार मृत्यु के विचार से हमें डरना चाहिए या जीवन को बेहतर जीना सीखना चाहिए? सोचिए। ... जीवन को बेहतर जीना सीखना चाहिए, क्योंकि मृत्यु का विचार हमें समय की क़ीमत सिखाता है और अच्छे कर्मों की ओर प्रेरित करता है।"),
],7)
